export function playRoulette(p) { const selected = p.payload?.color || 'red'; const number = Math.floor(Math.random() * 37); const color = number === 0 ? 'green' : number % 2 === 0 ? 'black' : 'red'; const win = selected === color; const multiplier = color === 'green' ? 14 : 2; const winAmount = win ? p.betAmount * multiplier : 0; return { game: 'roulette', selected, number, color, win, multiplier, winAmount }; }
